function dir$dmhotline_tdDisabledMasterField(p){
	p.setDisabled('ma_hl', true);
}
function dir$dmhotline_tdLoadData(p){
var maLoai = p.valForm('ma_loai');

	if(p.options.action ==  'NEW')
	{
		p.request('LoadCode', '', [['ma_loai', 'C', maLoai]]);

	}
}






