DECLARE @newCode VARCHAR(20);
DECLARE @ma_unit VARCHAR(32);

SELECT @ma_unit = ma_unit FROM sysunit WHERE unit_id = @@unit
DECLARE @maxNum  INT;

SELECT @maxNum = MAX(CAST(RIGHT(ma_hl, 4) AS INT))
FROM dmhotline
WHERE ma_loai = @ma_loai;

SET @maxNum = ISNULL(@maxNum, 0) + 1;

SET @newCode = @ma_loai + RIGHT('000' + CAST(@maxNum AS VARCHAR(4)), 4);

SELECT @newCode [!ma_hl]






